{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    raw_edges = case['distances']
    n = len(nodes)
    if n == 0:
        return {"mst_edges": [], "total_weight": 0.0}
    edges = []
    for a, b, d in raw_edges:
        u, v = (a, b) if a < b else (b, a)
        w = max(core[u], core[v], d)
        edges.append((u, v, w))
    edges.sort(key=lambda x: (x[2], x[0], x[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Graph not connected, cannot form MST")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
